import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@nativecn/ui/components/dialog";
import { Button } from "@nativecn/ui/components/button";

export default function App() {
  const [open, setOpen] = useState(false);
  return (
    <View>
      <Button onPress={() => setOpen(true)}>Open Dialog</Button>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirm Sign Out</DialogTitle>
            <DialogDescription>Are you sure you want to log out of your vault?</DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="ghost" onPress={() => setOpen(false)}>Cancel</Button>
            <Button variant="destructive" onPress={() => setOpen(false)}>Sign Out</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </View>
  );
}
